/* setAlimTemp */
INSERT INTO TB_ALTEMP (
            ALIM_SITU
          , TEMP_CODE
          , TEMP_TITL
          , ALIM_TITL
          , ALIM_ENTL
          , TEMP_CONT
          , TEMP_ENCT
          , USEE_YSNO
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{alimSitu}
          , #{tempCode}
          , #{tempTitl}
          , #{alimTitl}
          , #{alimEntl}
          , #{tempCont}
          , #{tempEnct}
          , #{useeYsno}
          , #{regiAdmn}
          , CURRENT_TIMESTAMP
          , #{updtAdmn}
          , CURRENT_TIMESTAMP
)

